import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Home from './Home';
// import Register from './Register'; // Uncomment this once you create Register.js

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* This is your main page with Login/Email/Password */}
          <Route path="/" element={<Home />} />
          
          {/* This is the page the 'Register' button links to */}
          <Route path="/register" element={<div>Register Page Coming Soon!</div>} />
          
        
        </Routes>
      </div>
    </Router>
  );
}

export default App;
